Output:
"use strict";

const SHOP1_DEBUG = false;

let WaveState = null;
let initialized = false;

let g_SelectedShop1Ability = "";
let g_SelectedShop1Ent = -1;
let g_SelectedShop1UnitName = "";
let g_SelectedShop1ModelUnitName = "";
let g_SelectedShop1Attack = 0;
let g_SelectedShop1Career = "";
let g_SelectedShop1CareerIcon = "";
let g_SelectedShop1ProjectileName = "";
let g_SelectedShop1Cooldown = 0;
let g_SelectedShop1DescriptionToken = "";
let g_SelectedShop1DescriptionVars = {};
let g_SelectedShop1ProxyEnt = -1;
let g_SelectedShop1PayloadHash = "";
let g_SelectedHeroEnt = -1;
let g_SelectedHeroPid = -1;
let g_SelectedHeroName = "";
let g_HeroStatsOpen = false;
let g_PlayerStatsByPid = {};
let g_HeroUiData = {};

function NormalizeImagePath(path) {
    if (!path) return "";
    let normalized = path;
    if (normalized.indexOf("s2r://") === 0) {
        normalized = normalized.substring("s2r://".length);
    } else if (normalized.indexOf("file://") === 0) {
        return normalized;
    }

    if (normalized.indexOf("panorama/") === 0) {
        normalized = normalized;
    }

    if (normalized.indexOf(".vtex_c") !== -1) {
        normalized = normalized.replace(/\.vtex_c$/i, ".vtex");
    }
    if (normalized.indexOf(".vsvg_c") !== -1) {
        normalized = normalized.replace(/\.vsvg_c$/i, ".vsvg");
    }

    const hasVtex = normalized.indexOf(".vtex") !== -1;
    const hasVsvg = normalized.indexOf(".vsvg") !== -1;
    if (!hasVtex && !hasVsvg) {
        normalized = normalized + ".vtex";
    }

    return "s2r://" + normalized;
}

function SetPanelImage(panel, path) {
    if (!panel || !panel.SetImage) return;
    panel.SetImage(NormalizeImagePath(path));
}

function GetHeroImagePath(heroName) {
    let data = g_HeroUiData && g_HeroUiData[heroName];
    if (!data) {
        data = CustomNetTables.GetTableValue("hero_ui", heroName);
        if (data) {
            g_HeroUiData[heroName] = data;
        }
    }

    if (data && data.ui_image) {
        return NormalizeImagePath(data.ui_image);
    }

    const baseHero = data && data.base_hero ? data.base_hero : heroName;
    return NormalizeImagePath("panorama/images/heroes/selection/" + baseHero + "_png.vtex_c");
}

function FormatStatValue(key, value) {
    if (value === undefined || value === null || !isFinite(value)) {
        return "--";
    }
    let scaled = value;
    if (key && (key.indexOf("Pct") !== -1 || key.indexOf("DamageScale") !== -1)) {
        scaled = value * 0.0001;
        const percent = Math.round(scaled * 10000) / 100;
        const text = Number.isInteger(percent) ? String(percent) : String(percent.toFixed(2));
        return text + "%";
    } else if (key === "ProjectileCooldown" || key === "SkillCooldown" || key === "AttackSpeed") {
        scaled = value * 0.01;
    }
    const rounded = Math.round(scaled * 100) / 100;
    return Number.isInteger(rounded) ? String(rounded) : String(rounded.toFixed(2));
}

function IsHeroEntity(ent) {
    if (Entities.IsHero) {
        return Entities.IsHero(ent);
    }
    const unitName = Entities.GetUnitName(ent) || "";
    return unitName.indexOf("npc_dota_hero_") === 0;
}

function IsShop1Dummy(ent) {
    const unitName = Entities.GetUnitName(ent) || "";
    return unitName.indexOf("npc_dota_auto_cast_dummy") === 0;
}

function IsShop1SelectionProxy(ent) {
    const unitName = Entities.GetUnitName(ent) || "";
    return unitName === "npc_dota_selection_proxy";
}

function WasRecentManualClick() {
    const cfg = GameUI.CustomUIConfig();
    const lastClick = cfg && cfg.last_left_click_time;
    if (!lastClick) return false;
    const now = Game.GetGameTime();
    return (now - lastClick) <= 0.35;
}

function WasRecentShop1ClickSelect() {
    const cfg = GameUI.CustomUIConfig();
    const lastClick = cfg && cfg.shop1_click_select_time;
    if (!lastClick) return false;
    const now = Game.GetGameTime();
    return (now - lastClick) <= 1.0;
}

function ShouldOpenShop1UiForSelection(entindex, proxyEnt) {
    const selected = GetSelectedEntity();
    if (!selected || selected === -1 || !Entities.IsValidEntity(selected)) {
        return false;
    }
    if (selected !== entindex && (proxyEnt === -1 || selected !== proxyEnt)) {
        return false;
    }
    return WasRecentManualClick() || WasRecentShop1ClickSelect();
}

function GetStatLabel(key) {
    if (!key) return "";
    const token = "dota_ability_variable_" + key.toLowerCase();
    const localized = $.Localize("#" + token);
    return localized && localized.indexOf("#") !== 0 ? localized : key;
}

function UpdateExtraRowVisibility() {
    const row = $("#TopBarExtraRow");
    if (!row) return;

    const shop1Row = $("#Shop1DummyRow");
    const heroRow = $("#HeroStatsRow");
    const shop1Visible = shop1Row && !shop1Row.BHasClass("Hidden");
    const heroVisible = heroRow && !heroRow.BHasClass("Hidden");

    if (shop1Visible || heroVisible) {
        row.RemoveClass("Hidden");
        SyncExtraRowWidth();
    } else {
        row.AddClass("Hidden");
    }
}

function SetShop1DummyVisible(show) {
    const row = $("#Shop1DummyRow");
    const overlay = $("#Shop1DummyAbilitiesOverlay");
    if (!row) return;

    const cfg = GameUI.CustomUIConfig();
    if (cfg) {
        cfg.shop1_dummy_visible = !!show;
    }

    if (show) {
        const wasHidden = row.BHasClass("Hidden");
        if (wasHidden) {
            UpdateShop1DummyPanel();
            UpdateShop1DummyAbilities(g_SelectedShop1Ent);
        }
        row.RemoveClass("Hidden");
        if (overlay) overlay.RemoveClass("Hidden");
    } else {
        row.AddClass("Hidden");
        if (overlay) overlay.AddClass("Hidden");
    }
    UpdateExtraRowVisibility();
}

function SetHeroStatsVisible(show) {
    const row = $("#HeroStatsRow");
    if (!row) return;

    g_HeroStatsOpen = !!show;
    if (g_HeroStatsOpen) {
        row.RemoveClass("Hidden");
    } else {
        row.AddClass("Hidden");
    }
    UpdateExtraRowVisibility();
}

function SetAbilityTooltip(panel, abilityName) {
    panel.ClearPanelEvent("onmouseover");
    panel.ClearPanelEvent("onmouseout");
    if (!abilityName) {
        return;
    }
    panel.SetPanelEvent("onmouseover", function () {
        $.DispatchEvent("DOTAShowAbilityTooltip", panel, abilityName);
    });
    panel.SetPanelEvent("onmouseout", function () {
        $.DispatchEvent("DOTAHideAbilityTooltip", panel);
    });
}

function UpdateHeroAbilities(ent) {
    const abilityPanels = [
        $("#HeroStatsAbility1"),
        $("#HeroStatsAbility2"),
        $("#HeroStatsAbility3")
    ];

    for (let i = 0; i < abilityPanels.length; i++) {
        const panel = abilityPanels[i];
        if (!panel) continue;

        const abilityIndex = Entities.GetAbility(ent, i);
        const abilityName = abilityIndex !== -1 ? Abilities.GetAbilityName(abilityIndex) : "";

        panel.abilityname = abilityName || "";
        panel.visible = !!abilityName;
        // SetAbilityTooltip(panel, abilityName);
        if (abilityName) {
            // const texture = Abilities.GetAbilityTextureName(abilityIndex) || "";
            // if (texture) {
            //     SetPanelImage(panel, "panorama/images/spellicons/" + texture + "_png.vtex_c");
            // } else {
            //     SetPanelImage(panel, "panorama/images/spellicons/empty_png.vtex_c");
            // }
            SetPanelImage(panel, "panorama/images/spellicons/empty_png.vtex_c");
        }
    }
}

function UpdateShop1DummyAbilities(ent) {
    const abilityPanels = [
        $("#Shop1DummyAbility1"),
        $("#Shop1DummyAbility2"),
        $("#Shop1DummyAbility3")
    ];

    for (let i = 0; i < abilityPanels.length; i++) {
        const panel = abilityPanels[i];
        if (!panel) continue;

        if (ent === -1 || !Entities.IsValidEntity(ent)) {
            panel.abilityname = "";
            panel.visible = false;
            // SetAbilityTooltip(panel, "");
            continue;
        }

        const abilityIndex = Entities.GetAbility(ent, i);
        const abilityName = abilityIndex !== -1 ? Abilities.GetAbilityName(abilityIndex) : "";

        // $.Msg("Shop1 Dummy Ability ", i, ": ", abilityName);

        if (abilityName) {
            panel.abilityname = abilityName;
            panel.visible = true;
            // const texture = Abilities.GetAbilityTextureName(abilityIndex) || "";
            // if (texture) {
            //     SetPanelImage(panel, "panorama/images/spellicons/" + texture + "_png.vtex_c");
            // } else {
            //     SetPanelImage(panel, "panorama/images/spellicons/empty_png.vtex_c");
            // }
            SetPanelImage(panel, "panorama/images/spellicons/empty_png.vtex_c");
            // SetAbilityTooltip(panel, abilityName);
        } else {
            panel.abilityname = "";
            panel.visible = true;
            SetPanelImage(panel, "panorama/images/spellicons/empty_png.vtex_c");
            // SetAbilityTooltip(panel, "");
        }
    }
}

function UpdateHeroStatsLabels(pid) {
    const stats = g_PlayerStatsByPid[pid];
    $("#HeroStatAttack").text = FormatStatValue("Attack", stats && stats.Attack);
    $("#HeroStatProjectileDamageFlat").text = GetStatLabel("ProjectileDamageFlat") + " " + FormatStatValue("ProjectileDamageFlat", stats && stats.ProjectileDamageFlat);
    $("#HeroStatProjectileDamagePct").text = GetStatLabel("ProjectileDamagePct") + " " + FormatStatValue("ProjectileDamagePct", stats && stats.ProjectileDamagePct);
    $("#HeroStatProjectileCooldown").text = GetStatLabel("ProjectileCooldown") + " " + FormatStatValue("ProjectileCooldown", stats && stats.ProjectileCooldown);
    $("#HeroStatProjectileRange").text = GetStatLabel("ProjectileRange") + " " + FormatStatValue("ProjectileRange", stats && stats.ProjectileRange);
}

function FormatNumber(value) {
    if (value === undefined || value === null || !isFinite(value)) {
        return "--";
    }
    const rounded = Math.round(value * 100) / 100;
    return Number.isInteger(rounded) ? String(rounded) : String(rounded.toFixed(2));
}

function SetScenePanelUnit(panel, unitName) {
    if (!panel || !unitName) return;
    if (panel._lastUnitName === unitName) {
        return;
    }
    panel._lastUnitName = unitName;
    if (!panel._sceneSet && panel.SetScene) {
        panel.SetScene("scenes/ui/hero_card/hero_card.vmap");
        panel._sceneSet = true;
    }
    if (panel.SetUnit) {
        panel.SetUnit(unitName, "idle", false);
    }
}

function SyncExtraRowWidth() {
    const top = $("#TopBarContent");
    const extra = $("#TopBarExtraRow");
    if (!top || !extra) return;
    const width = top.actuallayoutwidth;
    if (width && width > 0) {
        extra.style.width = width + "px";
    }
}

function UpdateHeroPanel() {
    const panel = $("#HeroStatsPanel");
    if (!panel) return;

    if (!g_SelectedHeroEnt || g_SelectedHeroEnt === -1 || !g_SelectedHeroName) {
        return;
    }

    const image = $("#HeroStatsImage");
    if (image) {
        SetScenePanelUnit(image, g_SelectedHeroName);
    }

    const nameLabel = $("#HeroStatsName");
    if (nameLabel) {
        const localized = $.Localize("#" + g_SelectedHeroName);
        nameLabel.text = localized && localized.indexOf("#") !== 0 ? localized : g_SelectedHeroName;
    }
    const attackIcon = $("#HeroStatsAttackIcon");
    if (attackIcon) {
        SetPanelImage(attackIcon, "panorama/images/control_icons/24px/attack_damage.vsvg_c");
    }

    UpdateHeroStatsLabels(g_SelectedHeroPid);
    UpdateHeroAbilities(g_SelectedHeroEnt);
}

function NormalizeShop1DummyPayload(event) {
    const unitName = event && event.unit_name ? event.unit_name : "";
    const modelUnitName = event && event.model_unit_name ? event.model_unit_name : unitName;
    return {
        ability: event && event.ability ? event.ability : "",
        entindex: event && event.entindex !== undefined ? event.entindex : -1,
        selection_proxy_entindex: event && event.selection_proxy_entindex !== undefined ? event.selection_proxy_entindex : -1,
        unit_name: unitName,
        model_unit_name: modelUnitName,
        attack_final: event && event.attack_final !== undefined ? event.attack_final : 0,
        career: event && event.career ? event.career : "",
        career_icon: event && event.career_icon ? event.career_icon : "",
        projectile_name: event && event.projectile_name ? event.projectile_name : "",
        projectile_interval: event && event.projectile_interval !== undefined ? event.projectile_interval : 0,
        description_token: event && event.description_token ? event.description_token : "",
        description_vars: event && event.description_vars ? event.description_vars : {}
    };
}

function BuildShop1DummyPayloadHash(data) {
    const vars = data && data.description_vars ? data.description_vars : {};
    const keys = Object.keys(vars).sort();
    const varsText = keys.map((key) => key + ":" + String(vars[key])).join("|");
    return [
        data.ability,
        data.unit_name,
        data.model_unit_name,
        data.attack_final,
        data.career,
        data.career_icon,
        data.projectile_name,
        data.projectile_interval,
        data.description_token,
        varsText
    ].join("#");
}

function ApplyShop1DummyPayload(data) {
    const hash = BuildShop1DummyPayloadHash(data);
    const changed = hash !== g_SelectedShop1PayloadHash;

    g_SelectedShop1PayloadHash = hash;
    g_SelectedShop1Ability = data.ability;
    g_SelectedShop1Ent = data.entindex;
    g_SelectedShop1ProxyEnt = data.selection_proxy_entindex;
    g_SelectedShop1UnitName = data.unit_name;
    g_SelectedShop1ModelUnitName = data.model_unit_name;
    g_SelectedShop1Attack = data.attack_final;
    g_SelectedShop1Career = data.career;
    g_SelectedShop1CareerIcon = data.career_icon;
    g_SelectedShop1ProjectileName = data.projectile_name;
    g_SelectedShop1Cooldown = data.projectile_interval;
    g_SelectedShop1DescriptionToken = data.description_token;
    g_SelectedShop1DescriptionVars = data.description_vars;

    return changed;
}

function UpdateShop1DummyPanel() {
    if (!g_SelectedShop1Ability || g_SelectedShop1Ent === -1) {
        return;
    }

    const model = $("#Shop1DummyModel");
    if (model && g_SelectedShop1ModelUnitName) {
        SetScenePanelUnit(model, g_SelectedShop1ModelUnitName);
    }

    const nameLabel = $("#Shop1DummyName");
    if (nameLabel) {
        const token = g_SelectedShop1UnitName ? "#" + g_SelectedShop1UnitName : "";
        const localized = token ? $.Localize(token) : "";
        nameLabel.text = localized && localized.indexOf("#") !== 0 ? localized : (g_SelectedShop1UnitName || "--");
    }

    const attackIcon = $("#Shop1DummyAttackIcon");
    if (attackIcon) {
        SetPanelImage(attackIcon, "panorama/images/control_icons/24px/attack_damage.vsvg_c");
    }
    const attackValue = $("#Shop1DummyAttackValue");
    if (attackValue) {
        attackValue.text = FormatNumber(g_SelectedShop1Attack);
    }

    const careerIcon = $("#Shop1DummyCareerIcon");
    if (careerIcon) {
        if (g_SelectedShop1CareerIcon) {
            SetPanelImage(careerIcon, g_SelectedShop1CareerIcon);
            careerIcon.visible = true;
        } else {
            careerIcon.SetImage("");
            careerIcon.visible = false;
        }
    }
    const careerText = $("#Shop1DummyCareerText");
    if (careerText) {
        const token = g_SelectedShop1Career ? "#" + g_SelectedShop1Career : "";
        const localized = token ? $.Localize(token) : "";
        careerText.text = localized && localized.indexOf("#") !== 0 ? localized : (g_SelectedShop1Career || "--");
    }

    const projName = $("#Shop1DummyProjectileName");
    if (projName) {
        const token = g_SelectedShop1ProjectileName ? "#" + g_SelectedShop1ProjectileName : "";
        const localized = token ? $.Localize(token) : "";
        projName.text = localized && localized.indexOf("#") !== 0 ? localized : (g_SelectedShop1ProjectileName || "--");
    }

    const cooldown = $("#Shop1DummyCooldown");
    if (cooldown) {
        const cd = FormatNumber(g_SelectedShop1Cooldown);
        const label = GetStatLabel("ProjectileInterval");
        cooldown.text = label + "：" + cd + "s";
    }

    const desc = $("#Shop1DummyDesc");
    const row = $("#Shop1DummyRow");
    if (desc) {
        if (g_SelectedShop1DescriptionVars) {
            for (const key of Object.keys(g_SelectedShop1DescriptionVars)) {
                const value = String(g_SelectedShop1DescriptionVars[key]);
                desc.SetDialogVariable(key, value);
                if (row) {
                    row.SetDialogVariable(key, value);
                }
            }
        }
        if (g_SelectedShop1DescriptionToken) {
            const token = g_SelectedShop1DescriptionToken[0] === "#"
                ? g_SelectedShop1DescriptionToken
                : "#" + g_SelectedShop1DescriptionToken;
            let text = $.Localize(token, row || desc);
            if (g_SelectedShop1DescriptionVars) {
                for (const key of Object.keys(g_SelectedShop1DescriptionVars)) {
                    const value = String(g_SelectedShop1DescriptionVars[key]);
                    const re = new RegExp("%" + key + "%", "g");
                    text = text.replace(re, value);
                }
            }
            desc.text = text;
        } else {
            desc.text = "";
        }
    }
}

function HandleForceClose() {
    const cfg = GameUI.CustomUIConfig();
    if (cfg && cfg.selection_force_close) {
        const now = Game.GetGameTime();
        if (!cfg.selection_force_close_time || (now - cfg.selection_force_close_time) <= 0.35) {
            SetShop1DummyVisible(false);
            SetHeroStatsVisible(false);
            cfg.selection_force_close = false;
            return true;
        }
        cfg.selection_force_close = false;
    }
    return false;
}



function GetSelectedEntity() {
    const pid = Players.GetLocalPlayer();
    const selected = Players.GetSelectedEntities(pid);
    if (!selected || selected.length < 1) {
        return -1;
    }
    return selected[0] || -1;
}

function OnShop1DummySelection(event) {
    const abilityName = event && event.ability ? event.ability : "";
    if (!abilityName) {
        g_SelectedShop1Ability = "";
        g_SelectedShop1Ent = -1;
        g_SelectedShop1UnitName = "";
        g_SelectedShop1ModelUnitName = "";
        g_SelectedShop1Attack = 0;
        g_SelectedShop1Career = "";
        g_SelectedShop1CareerIcon = "";
        g_SelectedShop1ProjectileName = "";
        g_SelectedShop1Cooldown = 0;
        g_SelectedShop1DescriptionToken = "";
        g_SelectedShop1DescriptionVars = {};
        g_SelectedShop1ProxyEnt = -1;
        SetShop1DummyVisible(false);
        return;
    }
    const cfg = GameUI.CustomUIConfig();
    if (SHOP1_DEBUG || (cfg && cfg.shop1_debug)) {
        $.Msg("[Shop1UI] selection event",
            "ent=", event && event.entindex,
            "proxy=", event && event.selection_proxy_entindex,
            "ability=", abilityName,
            "visible=", $("#Shop1DummyRow") && !$("#Shop1DummyRow").BHasClass("Hidden"));
    }
    const payload = NormalizeShop1DummyPayload(event);
    const row = $("#Shop1DummyRow");
    const nextHash = BuildShop1DummyPayloadHash(payload);
    const sameContent = nextHash === g_SelectedShop1PayloadHash;
    if (row && !row.BHasClass("Hidden") && sameContent && !(event && event.force_refresh)) {
        g_SelectedShop1Ent = payload.entindex;
        g_SelectedShop1ProxyEnt = payload.selection_proxy_entindex;
        return;
    }

    const changed = ApplyShop1DummyPayload(payload);
    if (row && !row.BHasClass("Hidden") && (changed || event && event.force_refresh)) {
        UpdateShop1DummyPanel();
        UpdateShop1DummyAbilities(g_SelectedShop1Ent);
    }

    if (SHOP1_DEBUG || (cfg && cfg.shop1_debug)) {
        $.Msg("[Shop1UI] selection event cached");
    }
    if (row && row.BHasClass("Hidden") && ShouldOpenShop1UiForSelection(payload.entindex, payload.selection_proxy_entindex)) {
        const cfgNow = GameUI.CustomUIConfig();
        if (cfgNow && cfgNow.shop1_click_select_time && WasRecentShop1ClickSelect()) {
            cfgNow.shop1_click_select_time = null;
        }
        SetShop1DummyVisible(true);
        SyncExtraRowWidth();
    }
}

function OnShop1DummyRefresh(event) {
    if (!event || event.entindex === undefined || event.entindex === null) {
        return;
    }
    if (g_SelectedShop1Ent !== event.entindex) {
        return;
    }
    const payload = NormalizeShop1DummyPayload(event);
    const changed = ApplyShop1DummyPayload(payload);

    const row = $("#Shop1DummyRow");
    if (row && !row.BHasClass("Hidden") && changed) {
        UpdateShop1DummyPanel();
        UpdateShop1DummyAbilities(g_SelectedShop1Ent);
    }
}

(function () {

    GameEvents.Subscribe("shop1_dummy_selection", OnShop1DummySelection);
    GameEvents.Subscribe("shop1_dummy_refresh", OnShop1DummyRefresh);
    GameEvents.Subscribe("update_stats", function (data) {
        if (!data || data.pid === undefined) {
            return;
        }
        g_PlayerStatsByPid[data.pid] = data.final || {};
        if (data.pid === g_SelectedHeroPid) {
            UpdateHeroStatsLabels(data.pid);
        }
    });

    // 监听 wave_info/state
    CustomNetTables.SubscribeNetTableListener("wave_info", (table, key, data) => {
        if (key === "state") {
            WaveState = data;

            // 第一次收到数据 → 显示整个 UI
            if (!initialized) {

                $("#TopBarContainer").RemoveClass("Hidden");
                $("#TopBarContainer").AddClass("Visible");

                $("#WaveScheduleContainer").RemoveClass("Hidden");
                $("#WaveScheduleContainer").AddClass("Visible");

                $("#Row_WaveCounter").RemoveClass("Hidden");
                $("#Row_WaveCounter").AddClass("Visible");

                initialized = true;
            }
        }
    });


    function Update() {
        HandleForceClose();
        if (WaveState) {

            const now = Game.GetGameTime();

            /* 第一行：Next / Alive / Boss */
            /* First Group: Level / Invasion / Boss */
            $("#Label_LevelInfo").text = $.Localize("#GameLevel") + (WaveState.game_level || 0);

            const nextRemain = Math.max(WaveState.next_wave_time - now, 0);
            $("#Label_WaveTimer").text = $.Localize("#Next") + Math.ceil(nextRemain) + "s";

            const expansionProgress = WaveState.expansion_progress || 0;
            const expansionGoal = WaveState.expansion_goal || 5;
            const expansionDone = !!WaveState.expansion_done;
            $("#Label_InvasionStatus").text = expansionDone
                ? $.Localize("#ExpansionProgressDone")
                : $.Localize("#ExpansionProgress");
            const barContainer = $("#Progress_InvasionBarContainer");
            if (barContainer) {
                barContainer.visible = !expansionDone;
            }

            // ------- 进度条更新 ---------
            let pct = expansionGoal > 0 ? (expansionProgress / expansionGoal) : 0;
            if (pct < 0) pct = 0;
            if (pct > 1) pct = 1;

            const bar = $("#Progress_InvasionBarFill");
            bar.style.width = (pct * 100) + "%";

            let color = "#FFFFFF";      // Safe: White

            if (pct >= 0.40 && pct < 0.70) color = "#E7BA01";      // Yellow
            else if (pct >= 0.70 && pct < 0.85) color = "#FF7F00"; // Orange
            else if (pct >= 0.85 && pct <= 1.00) color = "#FF3F3F"; // Red
            else if (pct > 1.0) color = "#A60000";                 // Dark Red (Over limit)

            bar.style.backgroundColor = color;
            $("#Text_InvasionProgress").text = expansionDone ? "" : (expansionProgress + " / " + expansionGoal);

            const bossRemain = Math.max(WaveState.next_boss_time - now, 0);
            $("#Label_BossTimer").text = $.Localize("#Boss") + Math.ceil(bossRemain) + "s";

            /* 第二行：Start 或 Wave */
            const preRemain = Math.max(WaveState.pre_delay_end_time - now, 0);

            if (preRemain > 0) {
                $("#Label_WaveStart").visible = true;
                $("#Label_WaveCount").visible = false;
                $("#Label_WaveStart").text = $.Localize("#Start") + Math.ceil(preRemain) + "s";
            } else {
                $("#Label_WaveStart").visible = false;
                $("#Label_WaveCount").visible = true;
                $("#Label_WaveCount").text = $.Localize("#Wave") + (WaveState.current_wave || 0);
            }
        }

        SyncExtraRowWidth();
        $.Schedule(0.1, Update);
    }

    Update();

    const barContainer = $("#Progress_InvasionBarContainer");
    if (barContainer) {
        barContainer.SetPanelEvent("onmouseover", function () {
            if (WaveState && WaveState.expansion_done) {
                return;
            }
            const progress = WaveState ? (WaveState.expansion_progress || 0) : 0;
            const goal = WaveState ? (WaveState.expansion_goal || 5) : 5;
            const tip = $.Localize("#ExpansionProgressTooltip_1") + " " + (goal - progress) + " " + $.Localize("#ExpansionProgressTooltip_2");
            $.DispatchEvent("DOTAShowTextTooltip", barContainer, tip);
        });
        barContainer.SetPanelEvent("onmouseout", function () {
            $.DispatchEvent("DOTAHideTextTooltip", barContainer);
        });
    }

})();


(function () {
