        if (table !== "hero_ui") return;
        if (key && data) {
            g_HeroUiData[key] = data;
        }
        UpdateHeroPanel();
    };

    CustomNetTables.SubscribeNetTableListener("hero_ui", heroUiListener);

    GameEvents.Subscribe("game_start", function () {
        g_HeroStatsOpen = false;
        SetHeroStatsVisible(false);
    });

    function HandleSelectedUnitUpdate() {
        const pid = Players.GetLocalPlayer();
        const selected = Players.GetSelectedEntities(pid);
        const ent = selected && selected.length > 0 ? selected[0] : -1;
        if (HandleForceClose()) return;

        if (ent === -1 || !Entities.IsValidEntity(ent)) {
            SetShop1DummyVisible(false);
            SetHeroStatsVisible(false);
            return;
        }

        if (IsShop1Dummy(ent) || IsShop1SelectionProxy(ent)) {
            SetHeroStatsVisible(false);
            const row = $("#Shop1DummyRow");
            if (!g_SelectedShop1Ability) {
                SetShop1DummyVisible(false);
                return;
            }
            if (row && row.BHasClass("Hidden") && !WasRecentManualClick() && !WasRecentShop1ClickSelect()) {
                return;
            }
            const cfg = GameUI.CustomUIConfig();
            if (cfg && cfg.shop1_click_select_time && WasRecentShop1ClickSelect()) {
                cfg.shop1_click_select_time = null;
            }
            SetShop1DummyVisible(true);
            return;
        }

        if (!IsHeroEntity(ent)) {
            SetShop1DummyVisible(false);
            SetHeroStatsVisible(false);
            return;
        }

        const prevHeroEnt = g_SelectedHeroEnt;
        if (g_HeroStatsOpen && ent === prevHeroEnt && WasRecentManualClick()) {
            return;
        }

        g_SelectedHeroEnt = ent;
        g_SelectedHeroPid = Entities.GetPlayerOwnerID(ent);
        g_SelectedHeroName = Entities.GetUnitName(ent) || "";

        UpdateHeroPanel();

        if (g_HeroStatsOpen) {
            return;
        }

        if (!WasRecentManualClick()) {
            return;
        }

        if (g_SelectedHeroPid !== -1) {
            GameEvents.SendCustomGameEventToServer("request_stats_for_pid", {
                target_pid: g_SelectedHeroPid
            });
        }

        SetHeroStatsVisible(true);
    }

    GameEvents.Subscribe("dota_player_update_selected_unit", HandleSelectedUnitUpdate);
    $.Schedule(0.1, HandleSelectedUnitUpdate);
})();

