+let g_TopBarDragActive = false;
+let g_TopBarDragStartCursor = null;
+let g_TopBarDragStartPos = null;
+let g_TopBarDragInitialized = false;
+
+function InitTopBarDrag() {
+    if (g_TopBarDragInitialized) return;
+    const container = $("#TopBarContainer");
+    const handle = $("#TopBarDragHandle");
+    if (!container || !handle) return;
+
+    g_TopBarDragInitialized = true;
+
+    handle.SetPanelEvent("onmousedown", function () {
+        if (!container) return;
+        g_TopBarDragActive = true;
+        g_TopBarDragStartCursor = GameUI.GetCursorPosition();
+        g_TopBarDragStartPos = {
+            x: container.actualxoffset || 0,
+            y: container.actualyoffset || 0
+        };
+
+        GameUI.SetMouseCallback(function (eventName) {
+            if (!g_TopBarDragActive) return false;
+
+            if (eventName === "mousemove") {
+                const cursor = GameUI.GetCursorPosition();
+                const dx = cursor[0] - g_TopBarDragStartCursor[0];
+                const dy = cursor[1] - g_TopBarDragStartCursor[1];
+                container.style.position = (g_TopBarDragStartPos.x + dx) + "px " +
+                    (g_TopBarDragStartPos.y + dy) + "px 0px";
+                return true;
+            }
+
+            if (eventName === "released" || eventName === "mouseout") {
+                g_TopBarDragActive = false;
+                GameUI.SetMouseCallback(null);
+                return true;
+            }
+
+            return false;
+        });
+    });
+}
